package com.lnxv.player.core.subtitle

import java.nio.charset.Charset
import org.junit.Assert.assertEquals
import org.junit.Test

/** Byte fixtures are generated by encoding known text with the target charset (no binary files in the repo). */
class SubtitleEncodingTest {
    private fun roundTrip(text: String, charset: String, expect: String = charset) {
        val bytes = text.toByteArray(Charset.forName(charset))
        assertEquals("detected charset for $charset", Charset.forName(expect), SubtitleEncoding.detect(bytes))
        assertEquals(text, SubtitleEncoding.decode(bytes))
    }

    private val cue = "1\n00:00:01,000 --> 00:00:03,000\n"

    @Test fun `hindi utf8`() = roundTrip(cue + "नमस्ते दुनिया, आप कैसे हैं? यह एक परीक्षण है।\n", "UTF-8")
    @Test fun `hindi utf16 with bom`() {
        val text = cue + "नमस्ते दुनिया, आप कैसे हैं?\n"
        val bytes = byteArrayOf(0xFF.toByte(), 0xFE.toByte()) + text.toByteArray(Charsets.UTF_16LE)
        assertEquals(Charsets.UTF_16LE, SubtitleEncoding.detect(bytes))
        assertEquals(text, SubtitleEncoding.decode(bytes))
    }
    @Test fun `utf8 with bom drops the bom`() {
        val bytes = byteArrayOf(0xEF.toByte(), 0xBB.toByte(), 0xBF.toByte()) + (cue + "héllo").toByteArray(Charsets.UTF_8)
        assertEquals(cue + "héllo", SubtitleEncoding.decode(bytes))
    }
    @Test fun `latin text in utf16le without bom`() {
        val bytes = (cue + "Hello there, this is plain English text.\n").toByteArray(Charsets.UTF_16LE)
        assertEquals(Charsets.UTF_16LE, SubtitleEncoding.detect(bytes))
    }
    @Test fun `ascii is utf8`() = assertEquals(Charsets.UTF_8, SubtitleEncoding.detect((cue + "Hello").toByteArray()))
    @Test fun `french in windows 1252`() =
        roundTrip(cue + "Où est-ce que vous allez? Je suis très fatigué après l'été, mais ça va.\n", "windows-1252")
    @Test fun `russian in windows 1251`() =
        roundTrip(cue + "Привет, как у тебя дела? Сегодня очень хорошая погода, не правда ли?\n", "windows-1251")
    @Test fun `arabic in windows 1256`() =
        roundTrip(cue + "مرحبا كيف حالك اليوم؟ الطقس جميل جدا في هذا الصباح.\n", "windows-1256")
    @Test fun `greek in windows 1253`() =
        roundTrip(cue + "Γεια σου, πώς είσαι σήμερα; Ο καιρός είναι πολύ ωραίος.\n", "windows-1253")
    @Test fun `japanese in shift jis`() =
        roundTrip(cue + "こんにちは、お元気ですか？今日はとても良い天気ですね。ありがとうございます。\n", "Shift_JIS")
    @Test fun `chinese in gbk`() =
        roundTrip(cue + "你好，你今天过得怎么样？今天天气非常好，我们一起去公园散步吧。\n", "GBK")
    @Test fun `korean in euc-kr`() =
        roundTrip(cue + "안녕하세요, 오늘 기분이 어떠세요? 오늘은 날씨가 정말 좋네요.\n", "EUC-KR")

    @Test fun `manual override wins over detection`() {
        val bytes = "Привет мир, это тест".toByteArray(Charset.forName("windows-1251"))
        assertEquals("Привет мир, это тест", SubtitleEncoding.decode(bytes, Charset.forName("windows-1251")))
    }
    @Test fun `choices resolve to real charsets`() {
        assertEquals(null, SubtitleEncoding.charsetFor("AUTO"))
        SubtitleEncoding.CHOICES.drop(1).forEach { org.junit.Assert.assertNotNull(SubtitleEncoding.charsetFor(it), it) }
    }
}
